// The public keys that may sign a release's firmware-manifest.json. They live in this source file, which is part of the
// site that is deployed, so a signature is never judged by a key that arrives with the release it signs.
// Signing and key management: docs/RELEASE_SIGNING.md.
//
// No release has been signed yet and no signing key has been generated for this project, so the list is empty and
// nothing is required. Do not put a key here that was not generated by the maintainer for this purpose.

export interface ReleaseKey {
  /** Short name the signature file refers to (`key_id`), for example `release-2026-a`. */
  id: string;
  /** Base64 of the raw 32-byte Ed25519 public key. */
  publicKey: string;
}

export const RELEASE_KEYS: readonly ReleaseKey[] = [];

/**
 * First release version (for example "0.4.0") whose manifest must carry a valid signature. Releases from this version
 * on are refused when the signature is missing, which stops an unsigned copy from replacing a signed release. Older
 * releases were never signed; they stay usable and are shown as "Not authenticated". `null` while no release is signed.
 */
export const SIGNATURE_REQUIRED_FROM: string | null = null;
